SELECT 
    SUM(QT_MAT_BAS) AS TOTAL_MATRICULAS_BÁSICA
FROM matriculas;

SELECT COUNT(DISTINCT NO_MUNICIPIO) 
FROM matriculas 
WHERE NO_MUNICIPIO IS NOT NULL;

SELECT COUNT(DISTINCT CO_ENTIDADE) 
FROM matriculas 
WHERE CO_ENTIDADE IS NOT NULL;

SELECT COUNT(DISTINCT CO_ENTIDADE) AS QUANTIDADE_REDE_PUBLICA, 
       COUNT(DISTINCT CO_ENTIDADE) - COUNT(DISTINCT CO_ENTIDADE) AS QUANTIDADE_REDE_PRIVADA 
FROM matriculas;

SELECT COUNT(DISTINCT CO_ENTIDADE) AS Rede_Pública, COUNT(DISTINCT CO_ENTIDADE) - 
COUNT(DISTINCT CO_ENTIDADE) OVER (ORDER BY SUM(QT_MAT_BAS) DESC) AS Rede_Privada
FROM matriculas;

SELECT DICIONARIO: IN_PODER_PUBLICO_PARCERIA
FROM matriculas
WHERE IN_PODER_PUBLICO_PARCERIA = 1;

SELECT SUM(QT_MAT_PROF_TEC) AS total_profissional_tecnica,
       ROUND(SUM(QT_MAT_PROF_TEC) / SUM(QT_MAT_PROF) * 100, 2) AS percentual_profissional_tecnica
FROM matriculas;

